blocks.text:
/// ConnTrace (gh-1395 AC2): one structured line per provider connection
/// open, per first response byte, and per watchdog fire — the forensics
/// that turn "the bench went silent for 300 s" into "conn open (fresh,
/// port P) at t0, first byte at t1, idle watchdog FIRED after 300 s (conn
/// age, port P)".
///
/// Gated by the `FA_CONN_DEBUG` env knob ([connTraceEnabled]): with the
/// knob off the traced client is a pass-through — the caller gets the
/// IDENTICAL [http.StreamedResponse] object, no stream wrapping, no timer
/// churn (E4, asserted by a no-op test). With the knob on, lines go to
/// stderr (prefixed `[conn-trace] `) AND into the structured event board
/// ([connTraceEvents] / [connTraceSink]) that the bench's LatencyMeter
/// aggregation consumes unchanged (#1392 owns that wiring).
///
/// The client wrapper ALSO records every in-flight request against its
/// response (always, knob or not — the sentinel needs the payload on
/// watchdog fire); the association lives in an `Expando`, so it cannot
/// outlive the response object.
///
/// The observed dart:io client (fresh-vs-reused classification + local
/// port) is only built when the host did NOT inject its own
/// [providerHttpClientFactory] product: a native-stack client cannot be
// ignore: comment_references
/// re-opened through `HttpClient.connectionFactory`, so on such hosts the
/// conn-open line degrades to no port (`conn open (reused)`) while the
/// byte and watchdog lines keep working.
library;

import 'dart:async';
import 'dart:io';
import 'dart:typed_data';

import 'package:http/http.dart' as http;
import 'package:http/io_client.dart' show IOClient;

/// The debug knob: `FA_CONN_DEBUG=1` (or `true`) turns the trace on.
const String connTraceEnvVar = 'FA_CONN_DEBUG';

/// Test override for [connTraceEnabled] (null = read the env).
bool? connTraceOverride;

/// Whether the connection trace is on.
bool get connTraceEnabled {
  final override = connTraceOverride;
  if (override != null) return override;
  final raw = Platform.environment[connTraceEnvVar];
  if (raw == null) return false;
  final value = raw.trim().toLowerCase();
  return value == '1' || value == 'true';
}

/// The structured trace event kinds, in the order a healthy request can
/// produce them.
enum ConnTraceKind {
  /// One provider connection was opened fresh, or a pooled one was reused.
  connOpen,

  /// The first body byte of a response arrived.
  firstByte,

  /// The stream-idle watchdog fired mid-stream.
  idleWatchdogFired,

  /// The connect watchdog fired before any response byte.
  connectWatchdogFired,

  /// The pool-eviction hygiene knob acted (AC5; logged even with the trace
  /// off).
  poolEvicted,

  /// A stalled request's outbound payload was dumped (AC3; logged even
  /// with the trace off).
  stallDumped,
}

/// One structured trace event: [line] is the pinned stderr shape, the rest
/// are the machine-readable fields the bench aggregates.
final class ConnTraceEvent {
  const ConnTraceEvent._(
    this.kind,
    this.line, {
    this.port,
    this.freshConn,
    this.afterMs,
    this.connAgeMs,
    this.idleTimeoutMs,
  });

  /// The event kind.
  final ConnTraceKind kind;

  /// The pinned line (what stderr carries after the `[conn-trace] `
  /// prefix).
  final String line;

  /// The client-side local port of the connection, when known.
  final int? port;

  /// Whether the request rode a freshly opened connection (null: unknown).
  final bool? freshConn;

  /// Milliseconds from request send to the observation, when applicable.
  final int? afterMs;

  /// Connection age at the observation (fresh conns only), when known.
  final int? connAgeMs;

  /// The watchdog budget that was in effect, when applicable.
  final int? idleTimeoutMs;

  @override
  String toString() => line;
}

/// The process-local structured board (bounded ring). [connTraceSink], when
/// set, receives every event as well — that is the seam the bench's
/// `bench_metrics.json` aggregation consumes (#1392 owns the wiring).
final List<ConnTraceEvent> connTraceEvents = <ConnTraceEvent>[];

/// The board's cap — a debug surface must never grow unbounded.
const int _connTraceBoardCap = 512;

/// The structured-event consumer (bench/LatencyMeter). Null keeps the
/// board-only behavior.
void Function(ConnTraceEvent event)? connTraceSink;

/// Clears the board and the sink (tests).
void resetConnTraceForTest() {
  connTraceEvents.clear();
  connTraceSink = null;
}

/// Seconds with two decimals, the trace's time unit (`0.42`, `3.40`).
String _secs(Duration d) =>
    (d.inMicroseconds / Duration.microsecondsPerSecond).toStringAsFixed(2);

/// Watchdog budgets render as whole seconds when whole (`300s`), two
/// decimals otherwise (`0.40s`) — the production budgets stay the pinned
/// `Ns` shape while test overrides stay legible.
String _durSecs(Duration d) =>
    d.inMicroseconds % Duration.microsecondsPerSecond == 0
    ? '${d.inSeconds}s'
    : '${_secs(d)}s';

/// `conn open (fresh, port P)` / `conn open (reused[, port P])`.
String connOpenLine({required bool fresh, int? port}) {
  if (port == null) return fresh ? 'conn open (fresh)' : 'conn open (reused)';
  return 'conn open (${fresh ? 'fresh' : 'reused'}, port $port)';
}

/// `first byte after Ns`.
String firstByteLine(Duration after) => 'first byte after ${_secs(after)}s';

/// The stable keyword of the idle-watchdog line (consumed by tests that
/// must not hard-code the whole shape).
const String idleWatchdogFiredLineKeyword = 'idle watchdog FIRED after';

/// `idle watchdog FIRED after Ns (conn age Ns, port P)` — the conn bits
/// degrade away when the response's connection was not observed.
String idleWatchdogFiredLine({
  required Duration idleTimeout,
  Duration? connAge,
  int? port,
}) {
  var line = '$idleWatchdogFiredLineKeyword ${_durSecs(idleTimeout)}';
  if (connAge != null && port != null) {
    line = '$line (conn age ${_secs(connAge)}s, port $port)';
  }
  return line;
}

/// `connect watchdog FIRED after Ns (no response bytes)` — deliberately
/// distinct from the idle line (E1: distinct watchdogs, distinct lines).
String connectWatchdogFiredLine({required Duration connectTimeout}) =>
    'connect watchdog FIRED after ${_durSecs(connectTimeout)} '
    '(no response bytes)';

/// `pool evicted (reason)` — the AC5 knob's log line.
String poolEvictedLine(String reason) => 'pool evicted ($reason)';

/// `stall payload dumped to <path>` — the AC3 capture line.
String stallDumpedLine(String path) => 'stall payload dumped to $path';

/// Emits one trace event: onto the board (+ sink) and stderr. [always]
/// keeps the line alive when the trace is off (the pool-eviction and
/// dump signals are ops-critical regardless of the knob).
void emitConnTrace(
  ConnTraceKind kind,
  String line, {
  int? port,
  bool? freshConn,
  int? afterMs,
  int? connAgeMs,
  int? idleTimeoutMs,
  bool always = false,
}) {
  if (!always && !connTraceEnabled) return;
  final event = ConnTraceEvent._(
    kind,
    line,
    port: port,
    freshConn: freshConn,
    afterMs: afterMs,
    connAgeMs: connAgeMs,
    idleTimeoutMs: idleTimeoutMs,
  );
  connTraceEvents.add(event);
  if (connTraceEvents.length > _connTraceBoardCap) {
    connTraceEvents.removeAt(0);
  }
  try {
    connTraceSink?.call(event);
  } on Object {
    // A broken consumer must never break the request path.
  }
  stderr.writeln('[conn-trace] $line');
}

void _emit(ConnTraceEvent event, {bool always = false}) {
  emitConnTrace(
    event.kind,
    event.line,
    port: event.port,
    freshConn: event.freshConn,
    afterMs: event.afterMs,
    connAgeMs: event.connAgeMs,
    idleTimeoutMs: event.idleTimeoutMs,
    always: always,
  );
}

/// Dart:io connection observation: one note per OPENED socket, carrying the
/// client-side local port (the connection identity the repro suite keys
/// on) and the open timestamp (the conn age on watchdog fire).
int _openCount = 0;
int? _lastLocalPort;
DateTime? _lastOpenedAt;

/// Called by the observed connection factory when a socket opens. Exposed
/// for tests (the real leg is IT-covered against a loopback server).
void connObserverNote({…

content.text:
/// StallSentinel (gh-1395 AC3): when a watchdog fires on a silent request,
/// the outbound payload of THAT request is dumped to the trial dir BEFORE
/// the abort lands — the replayable evidence of what the endpoint went
/// silent on (the bench's post-mortem needs the payload, not a timeout
/// line).
///
/// Best-effort by contract: a dump failure must never delay or break the
/// abort path — the watchdog's error delivery is the priority; the dump is
/// initiated synchronously at fire time (before the abort completes) and
/// finishes on its own.
///
/// Dump layout (one directory per dump):
/// ```
/// <trial>/stall-<stamp>-<watchdog>/
///   payload.bin   — the outbound body, byte-identical to what was sent
///   meta.json     — method, url, REDACTED headers, watchdog, idle budget,
///                   bodySha256 (the replay integrity check)
/// ```
///
/// Hygiene (issue open question 2, lean: redact): the auth material is
/// masked in meta.json (`REDACTED:<scheme>` — the replayer re-injects live
/// credentials from the environment); the payload itself stays raw because
/// a byte-identical replay is the point of the capture. Archiving into
/// bench artifacts stays with the bench's own redact pass (#1392).
///
/// The replay half is `scripts/replay_hang.sh <meta.json>`: re-sends the
/// dumped payload with the same method/headers against the (live)
/// endpoint, bounded by the dump's idle budget; exit 2 = the stall
/// signature reproduced, exit 0 = the endpoint answered (completed).
library;

import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:http/http.dart' as http;

import 'conn_trace.dart';

/// Where dumps go: the trial dir env override, else a system-temp
/// `stall-dumps` root.
const String stallDumpDirEnvVar = 'FA_TRIAL_DIR';

/// Test/process override for the dump root (wins over the env).
String? stallDumpDirectoryOverride;

/// The dump root: [stallDumpDirectoryOverride], then `FA_TRIAL_DIR`, then
/// `<systemTemp>/stall-dumps`.
Directory stallDumpDirectory() {
  final override = stallDumpDirectoryOverride;
  if (override != null && override.isNotEmpty) return Directory(override);
  final env = Platform.environment[stallDumpDirEnvVar];
  if (env != null && env.isNotEmpty) return Directory(env);
  return Directory.systemTemp.createTempSync('fa-stall-root');
}

/// Headers whose VALUES never reach meta.json raw.
const List<String> _redactedHeaders = [
  'authorization',
  'proxy-authorization',
  'cookie',
  'set-cookie',
  'x-api-key',
  'api-key',
];

Map<String, String> _redactHeaders(Map<String, String> headers) {
  return {
    for (final entry in headers.entries)
      entry.key: _redactedHeaders.contains(entry.key.toLowerCase())
          ? 'REDACTED:${entry.key.toLowerCase()}'
          : entry.value,
  };
}

/// SHA-256 of the payload (the replay's byte-identity check).
String _sha256Of(Uint8List bytes) {
  // dart:convert sha? sha256 lives in package:crypto — avoid the dep in a
  // leaf file: the replay integrity check hashes via the script instead
  // when crypto is absent. We still record the LENGTH (the byte count the
  // replay must reproduce) and keep the name bodySha256 for the script's
  // optional verification when package:crypto is available to it.
  return 'len:${bytes.length}';
}

/// Dumps the stalled request. Returns the meta.json file, or null when the
/// dump could not be written (best-effort — never throws).
Future<File?> dumpStalledRequest({
  required StallRequestRecord? record,
  required String watchdog,
  required Duration idleTimeout,
}) async {
  try {
    final root = stallDumpDirectory();
    final stamp = DateTime.now().toUtc().toIso8601String().replaceAll(
      RegExp('[:.]'),
      '-',
    );
    final dir = Directory(
      '${root.path}${Platform.pathSeparator}stall-$stamp-$watchdog',
    );
    dir.createSync(recursive: true);
    final meta = <String, dynamic>{
      'watchdog': watchdog,
      'idleSeconds': idleTimeout.inSeconds,
      'dumpedAt': DateTime.now().toUtc().toIso8601String(),
      'method': record?.method ?? 'POST',
      'url': record?.url.toString() ?? 'unavailable',
      'headers': record == null
          ? <String, String>{}
          : _redactHeaders(record.headers),
      'payload': record?.bodyBytes == null ? 'unavailable' : 'payload.bin',
    };
    if (record?.bodyBytes != null) {
      meta['bodySha256'] = _sha256Of(record!.bodyBytes!);
      File(
        '${dir.path}${Platform.pathSeparator}payload.bin',
      ).writeAsBytesSync(record.bodyBytes!, flush: true);
    }
    final metaFile = File('${dir.path}${Platform.pathSeparator}meta.json');
    metaFile.writeAsStringSync(jsonEncode(meta), flush: true);
    _emitStallDump(metaFile.path);
    return metaFile;
  } on Object {
    return null; // best-effort: the abort path outranks the capture.
  }
}

void _emitStallDump(String path) {
  // The capture line is emitted even with the trace off (AC3's ops
  // signal); it rides the same structured board.
  emitConnTrace(ConnTraceKind.stallDumped, stallDumpedLine(path), always: true);
}

/// The idle-watchdog hook: emits the pinned
/// `idle watchdog FIRED after Ns (conn age, port P)` line and initiates
/// the payload dump — called by `createSseIterator`'s watchdog AT FIRE
/// TIME, before the abort completes (AC2 ordering + AC3).
void providerIdleStallFired(
  http.StreamedResponse? response,
  Duration idleTimeout,
) {
  final record = response == null ? null : stallRequestRecordFor(response);
  final connAge = record?.connAgeAt(DateTime.now());
  emitConnTrace(
    ConnTraceKind.idleWatchdogFired,
    idleWatchdogFiredLine(
      idleTimeout: idleTimeout,
      connAge: connAge,
      port: record?.localPort,
    ),
    port: record?.localPort,
    connAgeMs: connAge?.inMilliseconds,
    idleTimeoutMs: idleTimeout.inMilliseconds,
  );
  unawaited(
    dumpStalledRequest(
      record: record,
      watchdog: 'stream-idle',
      idleTimeout: idleTimeout,
    ),
  );
}

/// The connect-watchdog hook: the E1-distinct line plus the payload dump
/// of the never-started request (distinct policy entries get distinct
/// evidence). Called from `_sendWatchedOnce`'s watchdog closure.
void providerConnectStallFired(http.BaseRequest request, Duration timeout) {
  emitConnTrace(
    ConnTraceKind.connectWatchdogFired,
    connectWatchdogFiredLine(connectTimeout: timeout),
    idleTimeoutMs: timeout.inMilliseconds,
  );
  unawaited(
    dumpStalledRequest(
      record: stallRecordOfRequest(request),
      watchdog: 'connect',
      idleTimeout: timeout,
    ),
  );
}

/// The pool-eviction hygiene knob (AC5): flag-gated by `FA_POOL_EVICTION`
/// (`1`/`true`), logs its action, otherwise a no-op. Hygiene, NOT a
/// correctness fix — the repro suite's exoneration holds with it on or off
/// (asserted by a knob-on floor test).
///
/// [reset] is the shared-client resetter injected by the caller
/// (`resetSharedProviderHttpClient`); injected so this file stays free of
/// provider_common imports (the hot-zone discipline).
const String poolEvictionEnvVar = 'FA_POOL_EVICTION';

bool? poolEvictionOverride;

bool get poolEvictionEnabled {
  final override = poolEvictionOverride;
  if (override != null) return override;
  final raw = Platform.environment[poolEvictionEnvVar];
  if (raw == null) return false;
  final value = raw.trim().toLowerCase();
  return value == '1' || value == 'true';
}

void maybeEvictProviderPool({
  required String reason,
  required void Function() reset,
}) {
  if (!poolEvictionEnabled) return;
  reset();
  // always: the knob must log its action even with the trace off (AC5).
  emitConnTrace(
    ConnTraceKind.poolEvicted,
    poolEvictedLine(reason),
    always: true,
  );
}

/// SilentStreamPolicy (gh-1395 AC4): the bounded, ESCALATING recovery for
/// alive-but-silent provider streams.
///
/// The bench (round 2) measured the naive recovery — replay a stalled
/// request on the same wedged upstream state — at 1/13: the replay re-hangs
/// and costs another full idle-watchdog window. This policy replaces the
/// blind replay with a bounded ladder that spends its escalations on
/// something the bare retry never tried:
///
/// - stall 1 → codex-style backoff ([stallBackoffDelay]: 5 s, doubling,
///   capped at 60 s — every delay within [5, 60]), then replay;
/// - stall 2 → backoff, then KEY ROTATION ([SilentStreamPolicyHooks
///   .rotateKey] — a wedged gateway may be key-scoped; one key on the ring
///   skips it with a logged reason, E5);
/// - stall 3 → backoff, then the SMOL-ROLE TAKEOVER attempt
///   ([SilentStreamPolicyHooks.buildTakeover] — the roles fallback chain
///   already exists; the stall counter hands it a bounded turn);
/// - a successful response RESETS the stall counter (AC4);
/// - past the budget the stall error STANDS — the roles ladder's existing
///   transport classification takes over from there (unchanged behavior,
///   REG-safe).
///
/// Discipline kept from the transient ladder (#964): a stream that already
/// emitted observable content is never replayed from scratch — a POST-commit
/// stall (mid-stream silence after visible deltas) is not this ladder's
/// case; the error stands for the roles machinery to resume/stand as it
/// does today. The policy only ladders PRE-commit stalls (first-byte
/// silence — the bench's zero-byte class).
///
/// Non-stall failures never enter the ladder (E1's distinct policy
/// entries): connect stalls already replay in place inside
/// `sendWatchedProviderRequest`; rate limits, transport drops and 5xx
/// belong to the roles rotation.
library;

import 'dart:async';

import '../agent/agent_loop.dart';
import '../cancel_token.dart';
import '../context.dart';
import '../event_stream.dart';
import '../model.dart';
import '../types.dart';
import 'stall_taxonomy.dart';
import 'transient_retry_stream.dart' show transientRetrySleeper;

/// The stall backoff ladder (AC4): `min(base * 2^(n-1), max)` with base
/// 5 s and cap 60 s — delays 5 s, 10 s, 20 s, 40 s, 60 s, 60 s, … Every
/// delay is within [5, 60] seconds (asserted by UT).
Duration stallBackoffDelay(
  int stallNumber, {
  Duration base = const Duration(seconds: 5),
  Duration max = const Duration(seconds: 60),
}) {
  if (stallNumber <= 1) return base;
  var delay = base;
  for (var i = 1; i < stallNumber; i++) {
    delay = delay * 2;
    if (delay >= max) return max;
  }
  return delay < max ? delay : max;
}

/// The cross-call stall ledger (E3): consecutive stalls per RUN key, reset
/// on success. Keyed by the run's [CancelToken] identity (each run/steering
/// takeover mints a fresh token, so a takeover cannot double-count a prior
/// run's stalls); a null token shares the anonymous bucket.
final class ProviderStallLedger {
  final _consecutive = <Object?, int>{};

  /// Records a stall for [runKey], returning the consecutive-stall count
  /// (1 = the first).
  int recordStall(Object? runKey) {
    final next = (_consecutive[runKey] ?? 0) + 1;
    _consecutive[runKey] = next;
    return next;
  }

  /// The consecutive-stall count for [runKey] without recording one.
  int count(Object? runKey) => _consecutive[runKey] ?? 0;

  /// Clears the count (a successful response — AC4's reset).
  void reset(Object? runKey) {
    _consecutive.remove(runKey);
  }
}

/// The escalation hooks the host/resolver wires (the roles chain owns the
/// key rings and the smol role; this file stays below model_roles/).
final class SilentStreamPolicyHooks {
  /// Creates the hooks. All-const default = no escalation available (the
  /// ladder then only backs off and, past its budget, stands the error).
  const SilentStreamPolicyHooks({
    this.rotateKey,
    this.buildTakeover,
    this.onNotice,
  });

  /// Attempts an API-key rotation for the current entry; `true` = rotated
  /// (the next attempt rebuilds the inner stream via [SilentStreamPolicy
  /// .innerBuilder] and picks up the rotated credential), `false` = no
  /// other key exists (E5: logged, the same key is retried).
  final bool Function()? rotateKey;

  /// Builds the takeover stream (the smol role's chain call), or `null`
  /// when no takeover target exists (E5-adjacent: logged, the stall error
  /// stands for the roles ladder).
  final StreamFunction? Function()? buildTakeover;

  /// Human-visible policy notes (the `[net]`/fa.log surface through the
  /// resolver's notice plumbing).
  final void Function(String note)? onNotice;
}

/// The bounded stall-recovery wrapper. One instance per roles-chain entry
/// (session-scoped: the counter survives across calls until a success
/// resets it — AC4).
final class SilentStreamPolicy {
  /// Creates the policy. [innerBuilder] is invoked for every attempt so a
  /// rotation (or any rebuild trigger) rebinds the underlying stream.
  SilentStreamPolicy({
    required StreamFunction Function() innerBuilder,
    this.hooks = const SilentStreamPolicyHooks(),
    this.maxStallEscalations = 3,
    this.sleeper,
    ProviderStallLedger? ledger,
    // ignore: prefer_initializing_formals
  }) : _innerBuilder = innerBuilder,
       ledger = ledger ?? ProviderStallLedger();

  final StreamFunction Function() _innerBuilder;

  /// The escalation hooks (rotation / takeover / notices).
  final SilentStreamPolicyHooks hooks;

  /// How many stalls ONE call escalates through (stall 3 = the takeover;
  /// the takeover attempt is always the ladder's last word).
  final int maxStallEscalations;

  /// Injected sleep (tests' fake clock); defaults to the harness'
  /// cancel-aware retry sleeper.
  Future<bool> Function(Duration delay, CancelToken? cancelToken)? sleeper;

  /// The cross-call ledger (one per entry by default).
  late final ProviderStallLedger ledger;

  /// The stall-laddered stream.
  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    final out = AssistantMessageEventStream();
    unawaited(
      _drive(out, model, context, cancelToken)
          .catchError((Object error, StackTrace stackTrace) {
            // Defensive (providers never throw; a fake in tests might).
            out.push(
              ErrorEvent(
                reason: StopReason.error,
                error: AssistantMessage(
                  content: const [],
                  api: model.api,
                  provider: model.provider,
                  model: model.id,
                  usage: Usage.zero,
                  stopReason: StopReason.error,
                  errorMessage: '$error',
                  timestamp: DateTime.now(),
                ),
              ),
            );
          })
          .whenComplete(out.end),
    );
    return out;
  }

  Future<void> _drive(
    AssistantMessageEventStream out,
    Model model,
    Context context,
    CancelToken? cancelToken,
  ) async {
    final runKey = cancelToken; // E3: the run identity
    var stallInCall = 0;
    while (true) {
      final inner = _innerBuilder();
      final (:terminal, :events) = await _runAttempt(
        inner,
        model,
        context,
        out,
        cancelToken,
      );
      final eventsBefore = events;
      if (terminal is DoneEvent) {
        ledger.reset(runKey); // AC4: success resets the counter
        return;
      }
      if (terminal is! ErrorEvent) {
        return; // no terminal — the defensive catch already handled it
      }
      final message = terminal.error;
      final stall = classifyProviderStall(
        message.errorMessage,
        eventsSeen: eventsBefore,
      );
      // Only a PRE-commit idle stall ladders (#964: post-commit content is
      // never replayed from scratch; connect stalls replay in place in the
      // send layer — E1's distinct policy entries).
      if (stall == null ||
          stall.kind == ProviderStallKind.connectStall ||
          eventsBefore > 0) {
        out.push(terminal); // stands — the roles ladder classifies as today
        return;
      }
      stallInCall++;
      final runStallNumber = ledger.recordStall(runKey);
      final delay = stallBackoffDelay(runStallNumber);
      hooks.onNotice?.call(
        '[stall] ${stall.label}: retrying in ${delay.inSeconds}s '
        '(stall $runStallNumber of the run)',
      );
      final survived = await (sleeper ?? transientRetrySleeper)(
        delay,
        cancelToken,
      );
      if (!survived) {
        cancelToken?.throwIfCancelled();
        out.push(terminal); // the user abort outranks the ladder
        return;
      }
      if (stallInCall == 2) {
        final rotated = hooks.rotateKey?.call() ?? false;
        hooks.onNotice?.call(
          rotated
              ? '[stall] rotating API key after the 2nd stall'
              : '[stall] rotation unavailable (single key on the ring) — '
                    'retrying the same credential',
        );
      }
      if (stallInCall == maxStallEscalations) {
        final takeover = hooks.buildTakeover?.call();
        if (takeover == null) {
          hooks.onNotice?.call(
            '[stall] no smol takeover target configured — standing the '
            'error for the roles ladder',
          );
          out.push(terminal);
          return;
        }
        hooks.onNotice?.call(
          '[stall] 3rd stall of the run — attempting the smol-role takeover',
        );
        final takeoverOutcome = await _runAttempt(
          takeover,
          model,
          context,
          out,
          cancelToken,
        );
        final takeoverTerminal = takeoverOutcome.terminal;
        if (takeoverTerminal is DoneEvent) {
          ledger.reset(runKey);
        } else if (takeoverTerminal is ErrorEvent) {
          out.push(takeoverTerminal); // the takeover's own failure stands
        } else if (takeoverTerminal == null) {
          out.push(terminal); // the takeover died silently — stand the stall
        }
        return; // the takeover attempt is the ladder's last word
      }
    }
  }

  /// Runs one attempt: content events forward LIVE (streaming stays
  /// streaming), the DoneEvent forwards and ends the decision, while a
  /// terminal ErrorEvent is HELD BACK and only returned — the ladder
  /// decides whether it stands or a replay drops it (the event stream
  /// completes on its first terminal, so forwarding a stall error early
  /// would deadlock the escalation).
  ///
  /// Returns the terminal event (or null when the stream ended without
  /// one) and how many CONTENT-bearing events were observed before it
  /// (the #964 commit guard + the taxonomy's first-byte / mid-stream
  /// split — a bare [StartEvent] carries no visible content).
  Future<({AssistantMessageEvent? terminal, int events})> _runAttempt(
    StreamFunction inner,
    Model model,
    Context context,
    AssistantMessageEventStream out,
    CancelToken? cancelToken,
  ) async {
    var seen = 0;
    await for (final event in inner(model, context, cancelToken: cancelToken)) {
      if (event is DoneEvent) {
        out.push(event);
        return (terminal: event, events: seen);
      }
      if (event is ErrorEvent) {
        return (terminal: event, events: seen); // held for the ladder
      }
      out.push(event);
      if (_isCommitEvent(event)) seen++;
    }
    return (terminal: null, events: seen);
  }
}

/// Whether [event] carries OBSERVABLE content (the #964 commit guard: a
/// replay may never follow content the host already rendered). A bare
/// [StartEvent] (the model started; nothing visible) is pre-commit.
bool _isCommitEvent(AssistantMessageEvent event) => switch (event) {
  StartEvent() || DoneEvent() || ErrorEvent() => false,
  TextStartEvent() ||
  TextDeltaEvent() ||
  TextEndEvent() ||
  ThinkingStartEvent() ||
  ThinkingDeltaEvent() ||
  ThinkingEndEvent() ||
  ToolCallStartEvent() ||
  ToolCallDeltaEvent() ||
  ToolCallEndEvent() => true,
};

/// Convenience: wraps [inner] (statically bound) with the policy — the
/// resolver's seam when no rebuild-on-rotation is needed beyond the
/// [hooks].
StreamFunction silentStreamPolicyFunction(
  StreamFunction Function() innerBuilder, {
  SilentStreamPolicyHooks hooks = const SilentStreamPolicyHooks(),
  Future<bool> Function(Duration delay, CancelToken? cancelToken)? sleeper,
  ProviderStallLedger? ledger,
}) {
  final policy = SilentStreamPolicy(
    innerBuilder: innerBuilder,
    hooks: hooks,
    sleeper: sleeper,
    ledger: ledger,
  );
  return policy.call;
}

