      'rotation after the 2nd, takeover attempt after the 3rd', () async {
    var rotations = 0;
    var takeovers = 0;
    final sharedInner = stallInner(3);
    final policy = SilentStreamPolicy(
      innerBuilder: () => sharedInner,
      hooks: SilentStreamPolicyHooks(
        rotateKey: () {
          rotations++;
