    // user-controlled text (provider/modelId labels).
    var sawUnknownProvider = false;
    for (final ref in refs) {
      final entry = _buildEntry(
        ref,
        skipped,
        role: role,
        onUnknownProvider: () => sawUnknownProvider = true,
      );
