      // never replayed from scratch; connect stalls replay in place in the
      // send layer — E1's distinct policy entries).
      if (stall == null ||
          stall.kind == ProviderStallKind.connectStall ||
          eventsBefore > 0) {
        out.push(terminal); // stands — the rol…

