  Map<String, String> _secrets;
  final DateTime Function() _now;
  final StreamFunction Function(String kind, String apiKey) _streamFactory;
  final _rings = <String, ApiKeyRing>{};
  final _wrappers = <String, FallbackStreamFunction>{};

