      expect(lines[0], contains('conn open (fresh, port '));
      expect(lines[1], contains('first byte after '));
      expect(lines[2], contains('idle watchdog FIRED after '));
      expect(lines[2], contains('conn age '));
      expect(lines[2], contains('port '));
