    switch (event) {
      case DoneEvent():
        _buffer.forEach(out.push);
        out.push(event);
        return const _Forwarded(succeeded: true);
      case ErrorEvent():
        return _forwardOrRetryable(out, event);
      case StartEvent():
        _buffer.add(event);
        return null;
      default:
