    for (var step = 1; step <= _credentials.length; step++) {
      final next = (start + step) % _credentials.length;
      final candidate = _credentials[next];
      if (!isInBackoff(candidate.name)) {
        _index = next;
        return candidate;
      }
    }
    return null;
