/// Builds an inner stream whose attempts 1..[stalls] die with the idle
/// stall wording (optionally after emitting [eventsBefore] data events),
/// then succeeds with a done event. Records how many times it was CALLED
/// and which "key" it was built for (the harness rotates by rebuilding
/// with the next key).
StreamFunction stallInner(
  int stalls, {
  int eventsBefore = 0,
  void Function(int attempt)? onAttempt,
}) {
  var attempt = 0;
  return (model, context, {cancelToken}) {
    attempt++;
    onAttempt?.call(attempt);
    final out = AssistantMessageEventStream();
    unawaited(() async {
      for (var i = 0; i < eventsBefore; i++) {
        // A CONTENT-bearing event (the #964 commit guard counts visible
        // content, not the bare start event).
        out.push(
          TextStartEvent(
            contentIndex: i,
            partial: AssistantMessage(
              content: const [],
              api: model.api,
              provider: model.provider,
    pushStreamErrorEvent(eventStream, state, error, cancelToken);
  } finally {
    eventStream.end();
    if (ownsClient) {
      httpClient.close();
    }
  }
}

/// Sends [request] (via [sendProviderRequest]), runs the adapter's
/// `onResponse` hook, and pushes the `StartEvent` with the initial snapshot.
///
/// Shared by the adapters: pi fires `start` right after the response headers
/// arrive, before the body stream is consumed.
Future<http.StreamedResponse> startProviderResponse(
  AssistantMessageEventStream eventStream,
  ProviderStreamState state,
  http.Client httpClient,
  http.Request request,
  CancelToken? cancelToken,
  FutureOr<void> Function(int statusCode, Map<String, String> headers, Model)?
  onResponse,
) async {
  final response = await sendProviderRequest(httpClient, request, cancelToken);
  await onResponse?.call(response.statusCode, response.headers, state.model);
  eventStream.push(StartEvent(partial: state.snapshot()));
  return response;
}

